class Rango:
    """Iterable reutilizable: cada for obtiene un iterador nuevo."""
    def __init__(self, inicio, fin):
        self.inicio = inicio
        self.fin = fin

    def __iter__(self):
        return IteradorRango(self.inicio, self.fin)


class IteradorRango:
    """Iterador: guarda la posición y solo sabe avanzar."""
    def __init__(self, actual, fin):
        self.actual = actual
        self.fin = fin

    def __iter__(self):
        return self              # un iterador es iterable de sí mismo

    def __next__(self):
        if self.actual >= self.fin:
            raise StopIteration  # contrato: señal de fin
        valor = self.actual
        self.actual += 1
        return valor


r = Rango(1, 4)
print(list(r), list(r))          # [1, 2, 3] [1, 2, 3]: reutilizable
print([(a, b) for a in r for b in r if a < b])   # bucles anidados sobre el mismo objeto
it = iter(r)
print(next(it), list(it))        # 1 [2, 3]

