import functools
import time

def temporizar(funcion):
    @functools.wraps(funcion)
    def envoltorio(*args, **kwargs):
        inicio = time.perf_counter()
        try:
            return funcion(*args, **kwargs)
        finally:                            # mide aunque la función lance una excepción
            envoltorio.tiempos.append(time.perf_counter() - inicio)
    envoltorio.tiempos = []                 # estado: un atributo en el propio envoltorio
    return envoltorio

