from datetime import date, datetime
from functools import singledispatch


@singledispatch
def formatear(valor):
    return str(valor)


@formatear.register
def _(valor: bool):
    return "sí" if valor else "no"


@formatear.register
def _(valor: int):
    return f"{valor:,}".replace(",", ".")


@formatear.register
def _(valor: float):
    ingles = f"{valor:,.2f}"                      # por ejemplo, '-1,234.50'
    return ingles.replace(",", "_").replace(".", ",").replace("_", ".")


@formatear.register(type(None))
def _(valor):
    return "—"


@formatear.register
def _(valor: list | tuple):
    return "; ".join(formatear(elemento) for elemento in valor)


@formatear.register
def _(valor: date):
    return valor.strftime("%d/%m/%Y")


@formatear.register
def _(valor: datetime):
    return valor.strftime("%d/%m/%Y %H:%M")

tests.code:
casos = {1234567: "1.234.567", 0: "0", 999: "999", -1000: "-1.000"}
for numero, esperado in casos.items():
    assert formatear(numero) == esperado, f"formatear({numero}) debe ser {esperado!r} y es {formatear(numero)!r}"

casos = {1234.5: "1.234,50", -0.5: "-0,50", 3.14159: "3,14", 1e6: "1.000.000,00"}
for numero, esperado in casos.items():
    assert formatear(numero) == esperado, f"formatear({numero}) debe ser {esperado!r} y es {formatear(numero)!r}"

assert hasattr(formatear, "registry"), "formatear debe estar decorada con @singledispatch"
for tipo in (bool, int, float, date, datetime):
    assert tipo in formatear.registry, f"Registra una implementación específica para {tipo.__name__} con @formatear.register"

exercises.explain:
`singledispatch` mira el tipo del primer argumento y busca en su registro la implementación del tipo más específico siguiendo la jerarquía de clases (el MRO). Por eso `True` usa la de `bool` y no la de `int`, y un `datetime` usa la suya y no la de `date`; si no hubieras registrado `bool`, `formatear(True)` devolvería `'1'`. La recursión en listas funciona porque cada elemento vuelve a pasar por el despachador.

Ventaja frente a una cadena de `if isinstance(...)`: la función queda **abierta a extensión**. Otro módulo puede añadir un tipo sin tocar tu código:
```python
from decimal import Decimal

@formatear.register
def _(valor: Decimal):
    return formatear(float(valor))
```
Con cadenas de `isinstance`, además, el orden importa: si compruebas `int` antes que `bool`, los booleanos salen mal. Puedes consultar qué implementación se usará con `formatear.dispatch(bool)`. En aplicaciones reales, el formato numérico por idioma se suele delegar en bibliotecas de internacionalización como Babel; el módulo `locale` también lo hace, pero cambia un estado global del proceso.

