import functools
import time


def reintentar(veces=3, excepciones=(Exception,), espera=0.0, factor=2.0, dormir=time.sleep):
    if veces < 1:
        raise ValueError("veces debe ser al menos 1")

    def decorador(funcion):
        @functools.wraps(funcion)
        def envoltorio(*args, **kwargs):
            pausa = espera
            for intento in range(1, veces + 1):
                try:
                    return funcion(*args, **kwargs)
                except excepciones:
                    if intento == veces:
                        raise
                    dormir(pausa)
                    pausa *= factor

        return envoltorio

    return decorador

exercises.setup:
def crear_inestable(fallos, excepcion=ConnectionError, resultado="ok"):
    """Devuelve una función que falla 'fallos' veces y después devuelve 'resultado'."""
    estado = {"llamadas": 0}

    def funcion(*args, **kwargs):
        estado["llamadas"] += 1
        if estado["llamadas"] <= fallos:
            raise excepcion(f"fallo {estado['llamadas']}")
        return resultado

    funcion.estado = estado
    return funcion

