try:
    g()
except KeyError:
    pass
else:
    raise AssertionError("Una excepción que no está en 'excepciones' debe propagarse al momento")
assert f.estado["llamadas"] == 1 and pausas == [], "Las excepciones no incluidas no se reintentan"

pausas = []
f = crear_inestable(10, excepcion=RuntimeError)
g = reintentar(dormir=pausas.append)(f)
try:
