from contextlib import ExitStack


def ejecutar_pasos(pasos):
    resultados = []
    with ExitStack() as pila:
        for hacer, deshacer in pasos:
            resultados.append(hacer())
            if deshacer is not None:
                pila.callback(deshacer)
        pila.pop_all()          # todo fue bien: se cancelan los deshacer pendientes
    return resultados

