from datetime import datetime
from itertools import groupby
from operator import itemgetter


def leer_lineas(ruta):
    """Genera las líneas del archivo sin el salto de línea final."""
    with open(ruta, encoding="utf-8") as archivo:
        for linea in archivo:
            yield linea.rstrip("\n")


def parsear(lineas):
    """Genera un dict por cada línea válida; ignora vacías, comentarios y mal formadas."""
    for linea in lineas:
        limpia = linea.strip()
        if not limpia or limpia.startswith("#"):
            continue
        campos = limpia.split()
        if len(campos) != 6:
            continue
        fecha, nivel, metodo, ruta, estado, ms = campos
        try:
            registro = {
                "fecha": datetime.fromisoformat(fecha),
                "nivel": nivel,
                "metodo": metodo,
                "ruta": ruta,
                "estado": int(estado),
                "ms": int(ms),
            }
        except ValueError:
            continue
        yield registro


def filtrar(registros, *, nivel=None, desde=None):
    """Genera los registros que cumplen los criterios indicados."""
    for registro in registros:
        if nivel is not None and registro["nivel"] != nivel:
            continue
        if desde is not None and registro["fecha"] < desde:
            continue
        yield registro


def resumen(registros):
    """Devuelve un dict con total, por_nivel, ms_medio y mas_lenta (una sola pasada)."""
    total = 0
    suma_ms = 0
    por_nivel = {}
    mas_lenta = None
    for registro in registros:
        total += 1
        suma_ms += registro["ms"]
        por_nivel[registro["nivel"]] = por_nivel.get(registro["nivel"], 0) + 1
        if mas_lenta is None or registro["ms"] > mas_lenta[1]:
            mas_lenta = (registro["ruta"], registro["ms"])
    return {
        "total": total,
        "por_nivel": por_nivel,
        "ms_medio": round(suma_ms / total, 1) if total else 0.0,
        "mas_lenta": mas_lenta,
    }


def rutas_con_errores(registros):
    """Devuelve [(ruta, errores)] ordenada por errores desc. y ruta asc."""
    por_ruta = itemgetter("ruta")
    errores = sorted((r for r in registros if r["estado"] >= 500), key=por_ruta)
    conteo = [(ruta, sum(1 for _ in grupo)) for ruta, grupo in groupby(errores, key=por_ruta)]
    return sorted(conteo, key=lambda par: (-par[1], par[0]))

