from functools import reduce
from itertools import groupby, islice


class Consulta:
    def __init__(self, fuente):
        self._fuente = fuente
        self._pasos = ()            # funciones: iterador -> iterador

    def _con_paso(self, paso):
        """Devuelve una Consulta NUEVA con la misma fuente y un paso más."""
        nueva = Consulta(self._fuente)
        nueva._pasos = self._pasos + (paso,)
        return nueva

    def __iter__(self):
        iterador = iter(self._fuente)
        for paso in self._pasos:
            iterador = paso(iterador)
        return iterador

    # --- Transformaciones (perezosas) ---
    def filtrar(self, predicado):
        return self._con_paso(lambda it: filter(predicado, it))

    def mapear(self, funcion):
        return self._con_paso(lambda it: map(funcion, it))

    def tomar(self, n):
        return self._con_paso(lambda it: islice(it, n))

    def saltar(self, n):
        return self._con_paso(lambda it: islice(it, n, None))

    def ordenar(self, clave=None, inverso=False):
        return self._con_paso(lambda it: iter(sorted(it, key=clave, reverse=inverso)))

    def unicos(self):
        def sin_repetidos(it):
            vistos = set()
            for elemento in it:
                if elemento not in vistos:
                    vistos.add(elemento)
                    yield elemento
        return self._con_paso(sin_repetidos)

    # --- Terminales ---
    def lista(self):
        return list(self)

    def primero(self, defecto=None):
        return next(iter(self), defecto)

    def contar(self):
        return sum(1 for _ in self)

    def reducir(self, funcion, inicial):
        return reduce(funcion, self, inicial)

    def agrupar(self, clave):
        ordenados = sorted(self, key=clave)
        return {k: list(grupo) for k, grupo in groupby(ordenados, key=clave)}

